        ts: Date.now(),
        score: res,
        // payload,
      };

      resultToken = await encryptToToken(pack);
      sessionStorage.setItem(STORAGE_TOKEN_KEY, resultToken);

      // закрываем тест, открываем apruve
closeWizard();
openApruve();

// ✅ ARM вручную: на мобилках часто НЕ приходит fd-form-submit
fdArmed = true;
fdArmTs = Date.now();
clearTimeout(fdTimer);
fdTimer = setTimeout(() => {
  fdArmed = false;
}, 60000);
    } catch (_) {
