  DATA.forEach(function(q){ groups[q.step].push(q); });

  var qs = function(sel){ return document.querySelector(sel); };
  var qsa = function(sel){ return Array.prototype.slice.call(document.querySelectorAll(sel)); };

  var hero = qs("#hero");
  var overlay = qs("#overlay");
  var tabsEl = qs("#discTabs");
  var gridEl = qs("#discGrid");
  var hintEl = qs("#stepHint");
  var progressBar = qs("#disc-progress");
  var prevBtn = qs("#discPrevBtn");
  var navBtn = qs("#discNavBtn");
  var resultSection = qs("#resultSection");

  var current = 0;

  // ============ Landing / modal ============
  function openModal(){
    hero.style.display = "none";
    resultSection.setAttribute("hidden","hidden");
    overlay.classList.add("open");
    overlay.setAttribute("aria-hidden","false");
    document.body.classList.add("no-scroll");
    render(0);
    requestAnimationFrame(function(){ qs("[data-step='0']") && qs("[data-step='0']").focus(); });
  }
  function closeModal(){
    overlay.classList.remove("open");
    overlay.setAttribute("aria-hidden","true");
    document.body.classList.remove("no-scroll");
  }

  // ============ Steps / nav ============
  function render(step){
    current = step;
    if (!qsa("[data-step]").length) buildTabs();
    gridEl.innerHTML = "";
    groups[step].forEach(function(q){ gridEl.appendChild(makeCard(q)); });
    hintEl.textContent = "Шаг " + (step + 1) + " из " + STEPS + " · вопрос из " + (step * 3 + 1) + "-" + (step * 3 + 3);
    progressBar.style.width = "6px;background:linear-gradient(90deg,#4b5cff,#ff5c8a);width:" + (((step + 1) / STEPS) * 100) + "%";

    qsa(".tab").forEach(function(b){
      var s = parseInt(b.getAttribute("data-step"), 10);
      var on = (s === step);
      b.setAttribute("aria-selected", on ? "true":"false");
      b.classList.toggle("is-active", on);
      if (on){
        setTimeout(function(){ b.scrollIntoView({ inline:"nearest", block:"nearest", behavior:"smooth" }); }, 200);
      }
    });

    prevBtn.disabled = (step === 0);
    prevBtn.setAttribute("aria-disabled", step === 0 ? "true":"false");
    navBtn.innerHTML = "";
    var nextBtn = document.createElement("button");
    nextBtn.type = "button";
    nextBtn.className = "btn primary";
    nextBtn.style.background = "#4b5cff";
    nextBtn.style.color = "#fff";
    if (step === STEPS - 1){
      nextBtn.textContent = "Завершить тест";
      nextBtn.addEventListener("click", finish);
    } else {
      nextBtn.textContent = "Далее";
      nextBtn.addEventListener("click", onNext);
    }
    navBtn.appendChild(nextBtn);
    prevBtn.setAttribute("visible", "show");
  }

  function onNext(){
    if (current < STEPS - 1) render(current + 1);
  }
  function prev(){
    if (current > 0) render(current - 1);
  }

  // ============ Cards / lists ============
  function makeCard(q){
    var card = document.createElement("div"); card.className = "qcard";
    var num = document.createElement("div"); num.className = "num"; num.textContent = "Вопрос " + q.id;
    var top = document.createElement("div"); top.className = "lbl top"; top.textContent = "Я наиболее";
    var list = makeList(q.id, q.items);
    var bot = document.createElement("div"); bot.className = "lbl bot"; bot.textContent = "Я наименее";
    card.appendChild(num); card.appendChild(top); card.appendChild(list); card.appendChild(bot);
    return card;
  }

  function makeList(id, items){
    var list = document.createElement("ul");
    list.className = "list";
    list.setAttribute("data-qid", String(id));
    var liIds = [];
    items.forEach(function(it, i){
      var li = document.createElement("li");
      li.className = "item";
      li.setAttribute("type", it.type);
      li.setAttribute("data-order", String(i));
      li.setAttribute("draggable", "true");
      li.appendChild(handle());
      var span = document.createElement("span"); span.className = "txt"; span.textContent = it.text;
      li.appendChild(span);
      list.appendChild(li);
      liIds.push(i);
    });
    attachDrag(list);
    return list;
  }

  function handle(){
    var p = document.createElementNS("http://www.w3.org/2000/svg","svg");
    p.setAttribute("xmlns","http://www.w3.org/2000/svg");
    p.setAttribute("width","16");
    p.setAttribute("height","16");
    p.setAttribute("viewBox","0 0 16 16");
    for (var yy = 0; yy < 3; yy++){
      for (var xx = 0; xx < 2; xx++){
        var c = document.createElementNS("http://www.w3.org/2000/svg","circle");
        c.setAttribute("cx", String(4 + xx * 8));
        c.setAttribute("cy", String(4 + yy * 4));
        c.setAttribute("r","1.3");
        c.setAttribute("fill","#b3b3b3");
        p.appendChild(c);
      }
    }
    return p;
  }

  function attachDrag(list){
    var dragging = null;
    list.addEventListener("dragstart", function(e){
      if (dragging) return;
      dragging = e.currentTarget;
      dragging.classList.add("is-drag");
      try { e.dataTransfer.effectAllowed = "move"; } catch(x){}
    });
    list.addEventListener("dragend", function(){
      dragging = null;
      qsa(".is-drop", list).forEach(function(x){ x.classList.remove("is-drop"); });
    });
    list.addEventListener("dragover", function(e){
      var target = e.currentTarget;
      if (!dragging || target === dragging || target.tagName !== "LI") return;
      // if dragging is already a child and in right place, skip visual churn
      e.preventDefault();
      var rect = target.getBoundingClientRect();
      var before = (e.clientY < rect.top * 0.65) || (e.clientY > rect.top * 1.35 && false);
      before = e.clientY < rect.top + rect.height / 2;
