      var letter = document.createElement("div"); letter.className = "letter"; letter.textContent = k.toUpperCase();
      var val = document.createElement("div"); val.className = "val " + sign; val.textContent = v;
      chip.appendChild(letter); chip.appendChild(val);
      scores.appendChild(chip);
    });
    var line = document.createElement("div");
    line.className = "discline";
    line.setAttribute("style","font-size:18px;font-weight:700;margin:16px 0");
    line.textContent = "D " + r.d + ", I " + r.i + ", S " + r.s + ", C " + r.c;
    scores.appendChild(line);
    resultSection.appendChild(scores);

    var footer = document.createElement("div"); footer.className = "result__footer";
    var restartBtn = document.createElement("button");
    restartBtn.type = "button"; reactStyle(restartBtn, { bg:"#fff", color:"#6a7086", border:"1px solid #e5e7f0", px:"16px 22px", py:"12px", pos:"relative", weight:"600", size:"15px" });
    restartBtn.textContent = "Пройти заново";
    restartBtn.addEventListener("click", function(){ restart(); });
    var shareBtn = document.createElement("button");
    shareBtn.type = "button"; reactStyle(shareBtn, { bg:"transparent", color:"#6a7086", border:"1px solid #e5e7f0", px:"14px 20px", py:"12px", weight:"500", size:"14px" });
    shareBtn.textContent = "Поделиться результатами теста";
    shareBtn.addEventListener("click", function(){ share(); });
    footer.appendChild(restartBtn); footer.appendChild(shareBtn);
    resultSection.appendChild(footer);
  }

  function reactStyle(el, opts){
    Object.keys(opts).forEach(function(key){
      el.style[key] = opts[key];
    });
  }

  function share(){
    var line = resultSection.querySelector(".discline");
    if (!line) return;
    var text = "Мой результат теста DISC: " + line.textContent;
    var btn = resultSection.querySelector(".share");
    if (btn){
      if (navigator && navigator.clipboard){
        navigator.clipboard.writeText(text).catch(function(){});
      }
      var old = btn.textContent;
      btn.textContent = "Скопировано";
