    overlay.setAttribute("aria-hidden", "true");
    document.body.classList.remove("no-scroll");
  }
  function buildTabs () {
    tabsEl.innerHTML = "";
    for (var s = 0; s < STEPS; s++) {
      (function () {
        var tab = document.createElement("button");
        tab.className = "tab"; tab.type = "button";
        tab.setAttribute("aria-selected", "false");
        tab.setAttribute("data-step", String(s));
        tab.textContent = "Шаг " + (s + 1);
        tab.addEventListener("click", function () {
          var target = parseInt(this.getAttribute("data-step"), 10);
          if (target <= current) render(target);
        });
        tabsEl.appendChild(tab);
      })();
    }
  }
  function render (step) {
    current = step;
    if (!qsa("[data-step]").length) buildTabs();
    gridEl.innerHTML = "";
    groups[step].forEach(function (q) { gridEl.appendChild(makeCard(q)); });
    hintEl.textContent = "Шаг " + (step + 1) + " из " + STEPS + " · вопрос " + (step * 3 + 1) + "-" + (step * 3 + 3);
    progressBar.style.width = (((step + 1) / STEPS) * 100) + "%";
    qsa(".tab").forEach(function (b) {
      var on = (parseInt(b.getAttribute("data-step"), 10) === step);
      b.setAttribute("aria-selected", on ? "true" : "false");
      b.classList.toggle("is-active", on);
      if (on) {
        setTimeout(function () { b.scrollIntoView({ inline: "nearest", block: "nearest", behavior: "smooth" }); }, 200);
      }
    });
    prevBtn.setAttribute("disabled", String(step === 0));
    navBtn.innerHTML = "";
    var b = document.createElement("button");
    b.type = "button"; b.className = "btn primary";
    b.style.background = "#4b5cff"; b.style.color = "#fff";
    if (step === STEPS - 1) {
      b.textContent = "Завершить тест";
      b.addEventListener("click", finish);
    } else {
      b.textContent = "Далее";
      b.addEventListener("click", function () { if (current < STEPS - 1) render(current + 1); });
    }
    navBtn.appendChild(b);
  }
  function makeCard (q) {
    var card = document.createElement("div"); card.className = "qcard";
    var num = document.createElement("div"); num.className = "num"; num.textContent = "Вопрос " + q.id;
    var top = document.createElement("div"); top.className = "lbl top"; top.textContent = "Я наиболее";
    var list = makeList(q.id, q.items);
    var bot = document.createElement("div"); bot.className = "lbl bot"; bot.textContent = "Я наименее";
    card.appendChild(num); card.appendChild(top); card.appendChild(list); card.appendChild(bot);
    return card;
  }
  function handle () {
    var NS = "http://www.w3.org/2000/svg";
    var svg = document.createElementNS(NS, "svg");
    svg.setAttribute("width", "16"); svg.setAttribute("height", "16");
    svg.setAttribute("viewBox", "0 0 16 16");
    for (var yy = 0; yy < 3; yy++)
      for (var xx = 0; xx < 2; xx++) {
        var c = document.createElementNS(NS, "circle");
        c.setAttribute("cx", String(4 + xx * 8));
        c.setAttribute("cy", String(4 + yy * 4));
        c.setAttribute("r", "1.3"); c.setAttribute("fill", "#b3b3b3");
        svg.appendChild(c);
      }
    return svg;
  }
  function makeList (id, items) {
    var list = document.createElement("ul");
    list.className = "list"; list.setAttribute("data-qid", String(id));
    items.forEach(function (it, i) {
      var li = document.createElement("li");
      li.className = "item";
      li.setAttribute("type", it.type);
      li.setAttribute("data-order", String(i));
      li.setAttribute("draggable", "true");
      li.appendChild(handle());
      var span = document.createElement("span"); span.className = "txt"; span.textContent = it.text;
      li.appendChild(span);
      list.appendChild(li);
    });
    attachDrag(list);
    return list;
  }
  function attachDrag (list) {
    var dragging = null;
    list.addEventListener("dragstart", function (e) {
      if (dragging) return;
      dragging = e.currentTarget;
      dragging.classList.add("is-drag");
      try { e.dataTransfer.effectAllowed = "move"; } catch (x) {}
    });
    list.addEventListener("dragend", function () {
      dragging = null;
      qsa(".is-drop", list).forEach(function (x) { x.classList.remove("is-drop"); });
    });
    list.addEventListener("dragover", function (e) {
      var target = e.currentTarget;
      if (!dragging || target === dragging || target.nodeName !== "LI") return;
      e.preventDefault();
      var rect = target.getBoundingClientRect();
      var before = e.clientY < rect.top + rect.height / 2;
      list.insertBefore(dragging, before ? target : target.nextSibling);
    });
  }
  function collect () {
    var payload = {};
    qsa(".list").forEach(function (list) {
      payload[list.getAttribute("data-qid")] = qsa(".item", list).map(function (li) {
        return { type: li.getAttribute("type"), order: li.getAttribute("data-order") };
      });
    });
    return payload;
  }
  function score (payload) {
    var res = { d: 0, i: 0, s: 0, c: 0 };
    qsa(".list").forEach(function (list) {
      var items = qsa(".item", list);
      items.forEach(function (li, idx) {
        var t = li.getAttribute("type");
        if (idx === 0) res[t]++;
        if (idx === items.length - 1) res[t]--;
      });
    });
    return res;
  }
  function finish () {
    var res = score(collect());
    hero.style.display = "none";
    closeModal();
    renderResult(res);
    resultSection.hidden = false;
    window.scrollTo({ top: 0, behavior: "smooth" });
  }
  function renderResult (r) {
    var h = document.createElement("h2");
    h.textContent = "Ваш DISC-профиль:";
    resultSection.appendChild(h);
    var disc = document.createElement("p");
    disc.className = "disclaimer";
    disc.innerHTML = "<b>Обратите внимание:</b> мы не даем расшифку ваших индивидуальных результатов. Вместо этого мы помогаем вам использовать Instrument для самооценки и работы с командами, сотрудниками и коллегами.";
    resultSection.appendChild(disc);
    var scores = document.createElement("div"); scores.className = "scores";
    ["d", "i", "s", "c"].forEach(function (k) {
      var chip = document.createElement("div"); chip.className = "score-chip";
      var v = r[k];
      var sig = v > 0 ? "pos" : (v < 0 ? "neg" : "zero");
      var letter = document.createElement("div"); letter.className = "letter"; letter.textContent = k.toUpperCase();
      var val = document.createElement("div"); val.className = "val " + sig; val.textContent = v;
      chip.appendChild(letter); chip.appendChild(val);
      scores.appendChild(chip);
    });
    var line = document.createElement("div");
    line.setAttribute("style", "font-size:18px;font-weight:700;margin:16px 0");
    line.textContent = "D " + r.d + ", I " + r.i + ", S " + r.s + ", C " + r.c;
    scores.appendChild(line);
    resultSection.appendChild(scores);
    var footer = document.createElement("div"); footer.className = "result__footer";
    var restart = document.createElement("button");
    restart.type = "button"; restart.className = "btn ghost";
    restart.style.background = "#fff"; restart.style.color = "#6a7086"; restart.style.border = "1px solid #e5e7f0";
    restart.textContent = "Пройти заново";
    restart.addEventListener("click", function () { restartTest(); });
    var share = document.createElement("button");
    share.type = "button"; share.className = "share";
    share.textContent = "Поделиться результатами теста";
    share.addEventListener("click", function () { shareResult(); });
    footer.appendChild(restart); footer.appendChild(share);
    resultSection.appendChild(footer);
  }
  function shareResult () {
    var line = resultSection.querySelector(".discline:not(.val)");
    line = resultSection.querySelector("div[style*='font-size:18px']");
    if (!line) return;
    var text = "Мой результат теста DISC: " + line.textContent;
