const puppeteer = require('/home/dp/MyProjects/disc/test-assignment/node_modules/puppeteer-core');
const path = require('path');

const FILE = 'file:///home/dp/MyProjects/disc/index.html';

(async () => {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-gpu']
  });
  const errors = [];
  const page = await browser.newPage();
  await page.setViewport({ width: 1000, height: 900 });
  page.on('pageerror', e => errors.push(String(e)));
  page.on('console', msg => { if (msg.type() === 'error') errors.push(msg.text()); });

  try {
    await page.goto(FILE, { waitUntil: 'networkidle0', timeout: 30000 });
  } catch (e) { /* ignore navigation timeout */ }

  await page.waitForFunction('document.querySelector("#discGrid").children.length === 3', { timeout: 5000 })
    .catch(() => {});

  const qidsAtStart = await page.$$eval('#discGrid .qcard', els => els.length);
  console.log('grid cards at step0:', qidsAtStart);

  // count items step 0
  const itemsStep0 = await page.$$eval('#discGrid .item', els => els.length);
  console.log('items at step0:', itemsStep0);

  // Click "Далее" 7 times to reach step 7, then finish
  let finished = false;
  for (let i = 0; i < 7; i++) {
    await page.evaluate(() => {
      const b = document.querySelector('#discNavBtn button');
      if (b) b.click();
    });
    await page.waitForTimeout(150);
  }

  // Now should be step 7; click finish
  const navBtnText = await page.$eval('#discNavBtn button', b => b.textContent).catch(() => '');
  console.log('nav button final text:', JSON.stringify(navBtnText));
  await page.evaluate(() => {
    const b = document.querySelector('#discNavBtn button');
    if (b) b.click();
  });
  await page.waitForTimeout(400);

  const resultVisible = await page.$eval('#resultSection', el => el.hidden === false);
  console.log('result visible after finish:', resultVisible);

  const scores = await page.$eval('#resultScores', el => el.innerHTML).catch(() => '');
  console.log('result scores markup present:', !!scores, 'len', scores.length);

  // Now simulate: reset test, do a deterministic ranking, then finish -> check scores
  // Open modal again
  await page.evaluate(() => {
    document.querySelector('#btnOpen').click();
  });
  await page.waitForFunction('document.querySelector("#overlay").classList.contains("open")', { timeout: 3000 }).catch(()=>{});
  await page.waitForTimeout(200);

  // For each question, set the order so that type 'd' at top (index0), 'i' at bottom (index3), others middle.
  // We'll just reorder items in DOM: sort by data-order ascending is already sorted.
  // Instead, we'll set first item type d, last type i by swapping.
  // Simplest: reorder each list so that we know scoring.
  // We'll assign: position 0 -> type "d", position 3 -> type "i" on every question.
  const QID_TYPES = [];
  for (let q = 0; q < 24; q++) {
    QID_TYPES.push(['d','x','x','i']);
  }
  for (let q = 0; q < 24; q++) {
    await page.evaluate((types) => {
      const lists = Array.from(document.querySelectorAll('.list'));
      lists.forEach(list => {
        const items = Array.from(list.querySelectorAll('.item'));
        // rebuild order: set type attributes to desired
        items.forEach((li, idx) => { li.setAttribute('type', types[idx]); });
      });
    }, QID_TYPES[q]);
  }

  // finish
  await page.evaluate(() => {
    document.querySelector('#discNavBtn button').click();
  });
  await page.waitForTimeout(400);

  const scoreVals = await page.$$eval('#resultScores .score-chip .val', els => els.map(e => e.textContent));
  console.log('computed scores for known layout (all major=d +1*24, minor=i -1*24):', scoreVals);
  // d should be +24, i should be -24, s=0,c=0
  await browser.close();
  console.log('PAGE ERRORS:', errors);
  if (errors.length) process.exit(3);
  process.exit(0);
})().catch(e => { console.error('PLAYTHROW ERROR', e); process.exit(1); });

