const puppeteer = require('/home/dp/MyProjects/disc/test-assignment/node_modules/puppeteer-core');
const FILE = 'file:///home/dp/MyProjects/disc/index.html';

// Deterministic scenario: every question sorted d, i, s, c (top-to-bottom).
// Scoring: position 0 (+1) is 'd' on all 24 => +24 on d.
//          position 3 (-1) is 'c' on all 24 => -24 on c.
// => expect { d: 24, i: 0, s: 0, c: -24 }
(async () => {
  const browser = await puppeteer.launch({ headless: 'new', args: ['--no-sandbox', '--disable-gpu'] });
  const errors = [];
  const page = await browser.newPage();
  page.on('pageerror', e => errors.push(String(e)));
  page.on('consolE', msg => { if (msg.type() === 'error') errors.push(msg.text()); });

  await page.goto(FILE, { waitUntil: 'domcontentloaded', timeout: 30000 }).catch(() => {});
  await page.click('#btnOpen');
  await page.waitForSelector('.overlay.is-open', { timeout: 3000 ).catch(() => {});

  const nCards = await page.$eval('#discGrid .qcard', els => els.length);
  const tabs = (await page.$$eval('.tab', els => els.map(e => e.textContent.trim()).join(','));
  console.log('cards0:', nCards, '| tabs:', tabs);

  let navClick = async () => {
    await page.evaluate(() => {
      const b = document.querySelector('#discNavBtn button');
      if (b) b.click();
    });
  };

  for (let i = 0; i < 7; i++) await navClick();
  await page.waitForTimeout(200);
  const navFinal = (await page.$eval('#discNavBtn button', b => b.textContent)).trim();
  console.log('navFinal:', navFinal);
  await navClick();
  await page.waitForTimeout(300);
  const resultHidden = await page.$eval('#resultSection', el => el.hidden);
  const resultLen = (await page.$eval('#resultScores', el => el.innerHTML)).length;
  console.log('resultHidden:', resultHidden, '| resultLen:', resultLen);
  if (resultHidden) { console.log('ERROR: result not shown on first run'); await browser.close(); process.exit(2); }

  // Reset wizard
  await page.evaluate(() => { document.querySelector('#discCloseBtn').click(); });
  await page.waitForTimeout(120);
  await page.click('#btnOpen');
  await page.waitForSelector('.overlay.is-open', { timeout: 3000 ).catch(() => {});
  await page.waitForTimeout(150);

  // Force each list order: types d, i, s, c (top->bottom); rebuild DOM so DOM order == types order
  await page.evaluate(() => {
    const NS = 'http://www.w3.org/2000/svg';
    const lists = document.querySelectorAll('.list');
    Array.prototype.forEach.call(lists, (list) => {
      list.innerHTML = '';
      ['d', 'i', 's', 'c'].forEach(function (t, idx) {
        var li = document.createElement('li');
        li.className = 'item';
        li.setAttribute('type', t);
        li.setAttribute('data-order', String(idx));
        li.setAttribute('draggable', 'true');
        var svg = document.createElementNS(NS, 'svg');
        svg.setAttribute('width', '16'); svg.setAttribute('height', '16'); svg.setAttribute('viewBox', '0 0 16 16');
        for (var yy = 0; yy < 3; yy++)
          for (var xx = 0; xx < 2; xx++) {
            var c = document.createElementNS(NS, 'circle');
            c.setAttribute('cx', String(4 + xx * 8));
            c.setAttribute('cy', String(4 + yy * 4));
            c.setAttribute('r', '1.3'); c.setAttribute('fill', '#b3b3b3');
            svg.appendChild(c);
          }
        li.appendChild(svg);
        var span = document.createElement('span');
        span.className = 'txt';
        li.appendChild(span);
        list.appendChild(li);
      });
    });
  });

  await navClick();
  await page.waitForTimeout(300);

  const vals = await page.$$eval('#resultScores .val', els => els.map(e => parseInt(e.textContent, 10)));
  console.log('scores d,i,s,c =', vals.join(','));
  console.log('sum =', vals.reduce((a, b) => a + b, 0));
  console.log('errors:', errors.length ? JSON.stringify(errors) : 'NONE');

  const ok = vals.length === 4 && vals[0] === 24 && vals[3] === -24 && vals[1] === 0 && vals[2] === 0;
  console.log(ok ? 'PLAYTHROUGH: PASS' : 'PLAYTHROUGH: FAIL');
  await browser.close();
  process.exit(errors.length || !ok ? 3 : 0);
}).catch(e => { console.error('PLAY', e); process.exit(1); });

