const puppeteer = require('/home/dp/MyProjects/disc/test-assignment/node_modules/puppeteer-core');
const FILE = 'file:///home/dp/MyProjects/disc/index.html';

(async function run () {
  const browser = await puppeteer.launch({ headless: 'new', args: ['--no-sandbox', '--disable-gpu'] });
  const errors = [];
  const page = await browser.newPage();
  page.on('pageerror', e => errors.push(String(e)));
  page.on('console', msg => {
    if (msg.type() === 'error') errors.push(msg.text());
  });
  await page.goto(FILE, { waitUntil: 'domcontentloaded', timeout: 30000 }).catch(() => {});
  await page.click('#btnOpen');
  const sel = '.overlay.is-open';
  await page.waitForSelector(sel, { timeout: 3000 }).catch(() => {});
  const nCards = await page.$eval('#discGrid .qcard', els => els.length);
  const tabs = (await page.$$eval('.tab', els => eles.map(e => e.textContent.trim()).join(', ')));
  console.log('cards0:', nCards, 'tabs:', tabs);

  function navClick () {
    return page.evaluate(function () {
      const b = document.querySelector('#discNavBtn button');
      if (b) b.click();
    });
