  console.log('resultHidden:', resultHidden, 'resultLen:', resultLen);
  if (resultHidden) {
    console.log('FAIL first-run result not visible');
    await browser.close();
    process.exit(2);
  }

  // reset
  await page.evaluate(function () { document.querySelector('#discCloseBtn').click(); });
  await page.waitForTimeout(120);
  await page.click('#btnOpen');
  await page.waitForSelector(sel, { timeout: 3000 }).catch(() => {});
  await page.waitForTimeout(150);

  // force order d,i,s,c
  await page.evaluate(function () {
    const lists = document.querySelectorAll('.list');
    Array.prototype.forEach.call(lists, function (list) {
      list.innerHTML = '';
      ['d', 'i', 's', 'c'].forEach(function (t, idx) {
        const li = document.createElement('li');
        li.className = 'item';
        li.setAttribute('type', t);
        li.setAttribute('data-order', String(idx));
        li.setAttribute('draggable', 'true');
        list.appendChild(li);
      });
    });
  });
  await navClick();
  await page.waitForTimeout(300);

  const vals = await page.$$eval('#resultScores .val', els => els.map(e => parseInt(e.textContent, 10)));
  console.log('scores:', vals.join(','));
  console.log('sum:', vals.reduce((a, b) => a + b, 0));
  console.log('errors:', errors.length ? JSON.stringify(errors) : 'NONE');
  const pass = vals.length === 4 && vals[0] === 24 && vals[3] === -24 && vals[1] === 0 && vals[2] === 0;
  console.log(pass ? 'PASS' : 'FAIL');
  await browser.close();
  process.exit((errors.length || !pass) ? 3 : 0);
})().catch(function (e) {
  console.error(e);
  process.exit(1);
});

