const puppeteer = require('/home/dp/MyProjects/disc/test-assignment/node_modules/puppeteer-core');
const sleep = ms => new Promise(function (r) { return setTimeout(r, ms); });
const FILE = 'file:///home/dp/MyProjects/disc/index.html';

(async function run () {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-gpu'],
    executablePath: '/usr/bin/google-chrome'
  });
  const errors = [];
  const page = await browser.newPage();
  page.on('pageerror', function (e) { return errors.push(String(e)); });
  page.on('console', function (msg) {
    if (msg.type() === 'error') return errors.push(msg.text());
  });
  await page.goto(FILE, { waitUntil: 'domcontentloaded', timeout: 30000 }).catch(function () {});
  await page.click('#btnOpen');
  const sel = '.overlay.is-open';
  await page.waitForSelector(sel, { timeout: 3000 }).catch(function () {});
  const cards0 = await page.$eval('#discGrid .qcard', function (els) { return els.length; });
  const tabText = (await page.$$eval('.tab', function (els) { return els.map(function (e) { return e.textContent; }).join(' '); }));
  console.log('cards0:', cards0, 'tabs:', tabText);

  const navClick = function () {
    return page.evaluate(function () {
      const b = document.querySelector('#discNavBtn button');
      if (b) b.click();
    });
  };

  for (let i = 0; i < 7; i++) await navClick();
  await sleep(200);
  const navFinal = (await page.$eval('#discNavBtn button', function (b) { return b.textContent; })).trim();
  console.log('navFinal:', navFinal);
  await navClick();
  await sleep(300);
  const resultHidden = await page.$eval('#resultSection', function (el) { return el.hidden; });
  const resultLen = (await page.$eval('#resultScores', function (el) { return el.innerHTML; })).length;
  console.log('resultHidden:', resultHidden, 'resultLen:', resultLen);
  if (resultHidden) {
    console.log('FAIL: result not visible on first run');
    await browser.close();
    process.exit(2);
  }

  await page.evaluate(function () { document.querySelector('#discCloseBtn').click(); });
  await sleep(120);
  await page.click('#btnOpen');
  await page.waitForSelector(sel, { timeout: 3000 }).catch(function () {});
  await sleep(150);

  await page.evaluate(function () {
    const lists = document.querySelectorAll('.list');
    Array.prototype.forEach.call(lists, function (list) {
      list.innerHTML = '';
      ['d', 'i', 's', 'c'].forEach(function (t, idx) {
        const li = document.createElement('li');
        li.className = 'item';
        li.setAttribute('type', t);
        li.setAttribute('data-order', String(idx));
        li.setAttribute('draggable', 'true');
        list.appendChild(li);
      });
    });
  });
  await navClick();
  await sleep(300);

  const vals = await page.$$eval('#resultScores .val', function (els) { return els.map(function (e) { return parseInt(e.textContent, 10); }); });
  console.log('scores:', vals.join(','));
  console.log('sum:', vals.reduce(function (a, b) { return a + b; }, 0));
  console.log('errors:', errors.length ? JSON.stringify(errors) : 'NONE');
  const pass = vals.length === 4 && vals[0] === 24 && vals[3] === -24 && vals[1] === 0 && vals[2] === 0;
  console.log(pass ? 'PASS' : 'FAIL');
  await browser.close();
  if (errors.length) process.exit(3);
  if (!pass) process.exit(4);
  process.exit(0);
})().catch(function (e) {
  console.error(e);
  process.exit(1);
});

